#include <bits/stdc++.h>

using namespace std;

long long n;

inline char nextchar();
inline long long read(char type);
inline void write(long long x);

int main()
{
    n = read('f');
    write(n - n / 2 - n / 3 - n / 5 - n / 7
          + n / 6 + n / 10 + n / 14 + n / 15 + n / 21 + n / 35
          - n / 30 - n / 42 - n / 70 - n / 105 + n / 210);
    return 0;
}

inline char nextchar()
{
    static char buf[100000], *p1 = buf, *p2 = buf;
    return (p1 == p2) &&
           (p2 = (p1 = buf) + fread(buf, 1, 100000, stdin), p1 == p2)
           ? EOF : *p1++;
}

inline long long read(char type)
{
    if (type == 'f')
    {
        long long p = 0;
        char ch = 0;
        bool sign = false;
        while (!isdigit(static_cast<unsigned char>(ch)))
        {
            sign |= (ch == '-');
            ch = nextchar();
        }
        while (isdigit(static_cast<unsigned char>(ch)))
        {
            p = p * 10 + (ch ^ 48);
            ch = nextchar();
        }
        return sign ? -p : p;
    }
    else
    {
        long long x = 0;
        int f = 1;
        char ch = getchar();
        while (ch < '0' || ch > '9')
        {
            if (ch == '-')
                f = -1;
            ch = getchar();
        }
        while (ch >= '0' && ch <= '9')
        {
            x = (x << 1) + (x << 3) + (ch ^ 48);
            ch = getchar();
        }
        return x * f;
    }
}

inline void write(long long x)
{
    static int stk[100];
    int top = 0;

    if (x == 0)
    {
        putchar('0');
        return;
    }

    if (x < 0)
    {
        x = -x;
        putchar('-');
    }

    while (x)
    {
        stk[++top] = x % 10;
        x /= 10;
    }

    while (top)
        putchar(stk[top--] + '0');
}

